def get_works_by_director(director_key):
    """根据导演 key 反查短剧"""
    return [w for w in WORKS_DATA.values() if w.get("director_key") == director_key]


def get_works_by_genre(genre):
    """按体裁筛选"""
    return [w for w in WORKS_DATA.values() if genre in w.get("genre", [])]


def get_works_by_platform(platform):
    """按平台筛选"""
    return [w for w in WORKS_DATA.values() if w.get("platform", "").lower() in platform.lower()]


def get_top_rated(n=10, min_rating=8.0):
    """获取 Top N 爆款短剧"""
    return sorted(
        [w for w in WORKS_DATA.values() if w.get("rating_douyin", 0) >= min_rating],
        key=lambda x: -x.get("rating_douyin", 0)
    )[:n]



# 兼容 works_corpus 的别名和函数
def get_extended_works():
    """兼容函数 - 返回所有作品"""
    return list(WORKS_DATA.values())


def get_hot_shortform_works():
    """兼容函数 - 返回所有作品"""
    return list(WORKS_DATA.values())


def get_rich_works():
    """兼容函数 - 返回所有作品(rich 库)"""
    return list(WORKS_DATA.values())


